@module keyQueue  src=keyQueue.lua  loc=90  mode=chunk  self=keyQueue
@deps ctx

# Invariants & contracts
  @invariant  one keyQueue per coordinator; each fill replaces the last frame's entries  @ 4
  @contract  take/takeAny remove what they return, so a claimed press is gone for every later reader  @ 6
  @contract  an owner named at the fill holds the frame; take/takeAny answer nil to others  @ 7
  @contract  held/mods read ImGui live, and answer the same whoever owns the queue  @ 8
  @contract  frameMods is the mask the fill stamped; a reader judges a chord by it, then takes at it  @ 9

# Shapes
  @shape  entry = { key: imguiKey, mods: modMask, repeated: bool }  @ 5

# Imports
  @require ImGui = 'imgui'  @ 11
  @require util = 'util'  @ 12

# Private state
  @state OWNERS = { help = true, modal = true, picker = true, statusEdit = ...  @ 17
  @state KEYS = {}  @ 21
  @state entries, owner, frameMask = {}, nil, 0  @ 39
  @state keyQueue = {}  @ 54

# Private functions
  @fn checked(name)  @ 43-48
      -- A name is one of the four owners or nobody; anything else is a typo, which would
      -- otherwise read as a key that quietly does nothing.
  @fn claimable(claimant)  @ 50-52

# Public API (keyQueue:*)
  @api keyQueue:fill(ownerNow)  @ 58-70
  @api keyQueue:take(key, mods, claimant)  @ 72-79
  @api keyQueue:takeAny(claimant)  @ 81-84
  @api keyQueue:held(key)  @ 86
  @api keyQueue:mods()  @ 87
  @api keyQueue:frameMods()  @ 88

# Uses (outbound edges)
  @use call    ImGui.GetKeyMods  @ fill:60 mods:87
  @use call    ImGui.IsKeyDown  @ held:86
  @use call    ImGui.IsKeyPressed  @ fill:64,67
  @use call    util.add  @ <load>:33 fill:65
  @use require imgui  @ <load>:11
  @use require util  @ <load>:12

# Calls (intra-file)
  @call checked  @ claimable:51 fill:59
  @call claimable  @ take:73 takeAny:82

# Unresolved receivers
  @drop name:sub  @ <load>:31

# Fields (r read / w write incl. constructor keys)
  @field r Mod_None  @ take:74
  @field r ctx  @ 14
  @field w help  @ 17
  @field r key  @ take:76
  @field w key  @ fill:65
  @field w modal  @ 17
  @field r mods  @ take:76
  @field w mods  @ fill:66
  @field w picker  @ 17
  @field w repeated  @ fill:67
  @field w statusEdit  @ 17
